class ExplicitPoint(val x: Int, val y: Int) {
    override fun equals(other: Any?): Boolean {
        return other is ExplicitPoint && x == other.x && y == other.y
    }

    override fun hashCode(): Int {
        return 31 * x + y
    }
}
